-- STRICTLY READ ONLY. Run before 202608290002_tyre_shop_accounting_voucher_link.sql.
with checks(check_name,status,details,blocking) as (
 values
 ('TYRE_PHASE_1_TABLES',case when to_regclass('public.tyre_shops') is not null and to_regclass('public.tyre_vehicle_entries') is not null and to_regclass('public.tyre_vehicle_entry_items') is not null then 'PASS' else 'FAIL' end,'Tyre Phase 1 source tables are required',true),
 ('TYRE_ENTRY_ENUM_FIX',case when to_regprocedure('public.save_vehicle_tyre_entry(uuid,uuid,date,public.tyre_source_type,uuid,public.tyre_work_type,text,bigint,text,jsonb)') is not null then 'PASS' else 'FAIL' end,'Final enum-safe Tyre entry RPC signature must exist',true),
 ('SOURCE_COLUMN_TYPES',case when (select data_type from information_schema.columns where table_schema='public' and table_name='tyre_vehicle_entries' and column_name='id')='uuid' and (select data_type from information_schema.columns where table_schema='public' and table_name='tyre_vehicle_entries' and column_name='adda_id')='uuid' and (select data_type from information_schema.columns where table_schema='public' and table_name='tyre_vehicle_entries' and column_name='vehicle_id')='uuid' and (select data_type from information_schema.columns where table_schema='public' and table_name='tyre_vehicle_entries' and column_name='total_amount')='numeric' then 'PASS' else 'FAIL' end,'Tyre source identity, tenant, vehicle and amount types',true),
 ('EXTERNAL_SOURCE_INTEGRITY',case when not exists(select 1 from public.tyre_vehicle_entries e left join public.tyre_shops s on s.id=e.tyre_shop_id left join public.vehicles v on v.id=e.vehicle_id where e.source_type='external_shop' and (s.id is null or s.shop_type<>'external_supplier' or s.adda_id<>e.adda_id or v.id is null or v.adda_id<>e.adda_id)) then 'PASS' else 'FAIL' end,'Every external-shop Tyre entry resolves to a same-Adda supplier and vehicle',true),
 ('ELIGIBLE_SOURCE_AMOUNTS',case when not exists(select 1 from public.tyre_vehicle_entries where source_type='external_shop' and total_amount<=0) then 'PASS' else 'FAIL' end,'Eligible supplier liabilities must have positive authoritative totals',true),
 ('NO_ORPHAN_TYRE_RELATIONS',case when not exists(select 1 from public.tyre_vehicle_entry_items i left join public.tyre_vehicle_entries e on e.id=i.tyre_vehicle_entry_id left join public.tyre_assets a on a.id=i.tyre_asset_id left join public.vehicle_tyre_positions p on p.id=i.vehicle_position_id where e.id is null or(i.tyre_asset_id is not null and a.id is null)or(i.vehicle_position_id is not null and p.id is null)) then 'PASS' else 'FAIL' end,'Existing Tyre entry items resolve to their source, serial asset and position',true),
 ('TYRE_ACCOUNT_OBJECTS_ABSENT',case when to_regclass('public.tyre_shop_bills') is null and to_regclass('public.tyre_shop_payments') is null and to_regclass('public.tyre_shop_payment_allocations') is null then 'PASS' else 'FAIL' end,'Tyre accounting tables must be absent before first deployment',true),
 ('TYRE_ACCOUNT_RPC_CONFLICTS',case when not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('rebuild_tyre_shop_accounting','save_tyre_shop_payment','delete_tyre_shop_payment')) then 'PASS' else 'FAIL' end,'No conflicting Tyre accounting RPC overloads',true),
 ('MIGRATION_HISTORY_PENDING',case when to_regclass('supabase_migrations.schema_migrations') is null or not exists(select 1 from supabase_migrations.schema_migrations where version='202608290002') then 'PASS' else 'FAIL' end,'Migration version 202608290002 must still be pending',true),
 ('VOUCHER_DEPENDENCIES',case when to_regclass('public.expenses') is not null and to_regclass('public.expense_items') is not null and to_regclass('public.loadings') is not null and to_regclass('public.bookings') is not null and to_regclass('public.vehicles') is not null then 'PASS' else 'FAIL' end,'Voucher vehicle/Adda context dependencies',true),
 ('VOUCHER_ID_TYPES',case when (select data_type from information_schema.columns where table_schema='public' and table_name='expenses' and column_name='id')='bigint' and (select data_type from information_schema.columns where table_schema='public' and table_name='loadings' and column_name='id')='bigint' and (select data_type from information_schema.columns where table_schema='public' and table_name='loadings' and column_name='booking_id')='uuid' then 'PASS' else 'FAIL' end,'Voucher/loading identity contract',true),
 ('VOUCHER_ITEM_CONTRACT',case when (select data_type from information_schema.columns where table_schema='public' and table_name='expense_items' and column_name='expense_id')='bigint' and (select data_type from information_schema.columns where table_schema='public' and table_name='expense_items' and column_name='expense_type')='text' and (select data_type from information_schema.columns where table_schema='public' and table_name='expense_items' and column_name='amount')='numeric' then 'PASS' else 'FAIL' end,'Voucher item identity, type and amount contract',true),
 ('VOUCHER_TYRE_OBJECTS_ABSENT',case when to_regclass('public.voucher_tyre_entries') is null and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='sync_voucher_tyre_entries') then 'PASS' else 'FAIL' end,'No conflicting Voucher-Tyre relationship or RPC',true),
 ('WORKSHOP_LINK_PRESENT',case when to_regclass('public.voucher_workshop_entries') is not null then 'PASS' else 'FAIL' end,'Deployed Workshop reference-link precedent',true),
 ('OIL_LINK_PRESENT',case when to_regclass('public.voucher_oil_entries') is not null and to_regprocedure('public.sync_voucher_oil_entries(bigint,uuid[])') is not null then 'PASS' else 'FAIL' end,'Deployed Oil reference-link precedent',true),
 ('WORKSHOP_OIL_PAYMENT_BOUNDARIES',case when to_regprocedure('public.save_workshop_payment(bigint,uuid,date,numeric,numeric,text,text,text)') is not null and to_regprocedure('public.save_oil_supplier_payment(bigint,uuid,date,numeric,numeric,text,text,text)') is not null then 'PASS' else 'FAIL' end,'Existing Workshop and Oil payment authorities must remain deployed',true),
 ('VOUCHER_CASHBOOK_FUNCTION',case when to_regprocedure('public.ut_sync_voucher_cashbook(text)') is not null then 'PASS' else 'FAIL' end,'Existing Voucher Cashbook synchronizer',true),
 ('EXISTING_REFERENCE_EXCLUSIONS',case when pg_get_functiondef(to_regprocedure('public.ut_sync_voucher_cashbook(text)')) ilike '%voucher_workshop_entries%' and pg_get_functiondef(to_regprocedure('public.ut_sync_voucher_cashbook(text)')) ilike '%voucher_oil_entries%' then 'PASS' else 'FAIL' end,'Workshop and Oil reference exclusions must be preserved',true),
 ('CASHBOOK_AUTOMATIC_REFERENCE',case when to_regclass('public.cashbook_entries_automatic_reference_uidx') is not null or to_regclass('public.cashbook_entries_oil_supplier_reference_uidx') is not null then 'PASS' else 'FAIL' end,'Reviewed automatic-reference uniqueness exists',true),
 ('CASHBOOK_COLUMN_CONTRACT',case when not exists(select 1 from(values('entry_date'),('entry_type'),('person_type'),('person_name'),('payment_method'),('amount'),('description'),('reference_type'),('reference_id')) required(column_name) where not exists(select 1 from information_schema.columns c where c.table_schema='public' and c.table_name='cashbook_entries' and c.column_name=required.column_name)) then 'PASS' else 'FAIL' end,'Cashbook columns required by payment_now synchronization exist',true),
 ('TYRE_PAYMENT_CASHBOOK_EMPTY',case when not exists(select 1 from public.cashbook_entries where reference_type='tyre_shop_payment') then 'PASS' else 'FAIL' end,'No unexplained pre-deployment Tyre Shop payment rows',true),
 ('TENANT_HELPERS',case when to_regprocedure('public.current_user_adda_id()') is not null and to_regprocedure('public.current_user_role()') is not null and to_regprocedure('public.is_super_admin()') is not null then 'PASS' else 'FAIL' end,'Required Adda/auth helpers',true),
 ('SOURCE_RLS',case when coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.tyre_vehicle_entries')),false) and coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.tyre_shops')),false) then 'PASS' else 'FAIL' end,'Tyre source RLS remains enabled',true),
 ('LEGACY_VOUCHER_CONTEXT',case when not exists(select 1 from public.expenses e join public.loadings l on l.id=e.loading_id left join public.bookings b on b.id=l.booking_id left join public.vehicles v on v.id=l.vehicle_id left join public.addas a on a.id=case when l.booking_id is null then v.adda_id else b.adda_id end where l.id is null or v.id is null or a.id is null or (l.booking_id is not null and b.id is null)) then 'PASS' else 'FAIL' end,'Every Voucher resolves through Booking/Adda or legacy Loading/Vehicle/Adda context',true),
 ('COUNTS','INFO',format('%s eligible external-shop Tyre entries; %s Vouchers; %s Tyre payment Cashbook rows',(select count(*) from public.tyre_vehicle_entries where source_type='external_shop' and total_amount>0),(select count(*) from public.expenses),(select count(*) from public.cashbook_entries where reference_type='tyre_shop_payment')),false)
), combined as (
 select 'OVERALL_TYRE_ACCOUNTING_VOUCHER_PREFLIGHT'::text check_name,case when count(*) filter(where blocking and status='FAIL')=0 then 'PASS' else 'FAIL' end status,format('%s blocking check(s) failed; %s passed; %s informational',count(*) filter(where blocking and status='FAIL'),count(*) filter(where status='PASS'),count(*) filter(where status='INFO')) details from checks
 union all select check_name,status,details from checks
)
select check_name,status,details from combined order by case when check_name='OVERALL_TYRE_ACCOUNTING_VOUCHER_PREFLIGHT' then 0 else 1 end,check_name;
